// Approved topics without an article, from the dashboard.
const rows = $('Get Approved Topics').all().filter(item => item.json.topic_id);

return rows.map((item, i) => ({
  json: {
    topic_id: item.json.topic_id,
    row_number: i + 1,
    selected_keyword: item.json.selected_keyword,
    secondary_keywords: Array.isArray(item.json.secondary_keywords) ? item.json.secondary_keywords : [],
    topic: item.json.topic || '',
    angle: item.json.angle || '',
    category: item.json.category || '',
    client_name: item.json.client_name || ''
  }
}));

const client = $('Read Client Profile1').first().json;
const currentTopic = $json;

const urls = (client.Competitors || '').split(/[\n,]/).map(s => s.trim()).filter(Boolean);
const top = urls.slice(0, 2);

return top.map(url => ({
  json: {
    competitor_url: url,
    row_number: currentTopic.row_number,
    selected_keyword: currentTopic.selected_keyword,
    topic: currentTopic.topic,
    angle: currentTopic.angle,
    category: currentTopic.category,
    client_name: currentTopic.client_name
  }
}));

const input = items[0].json;
let text;
let topic;

if (input.data && input.data.markdown) {
  text = (input.data.markdown || '').substring(0, 1500);
  topic = $('Prepare Manual Competitors2').first().json;
} else if (input.candidates) {
  text = input.candidates[0]?.content?.parts?.[0]?.text || '';
  topic = $('Prepare Manual Competitors2').first().json;
} else {
  text = input.competitor_analysis_text || '';
  topic = input;
}

return [{
  json: {
    competitor_analysis_text: text,
    row_number: topic.row_number,
    selected_keyword: topic.selected_keyword,
    topic: topic.topic,
    angle: topic.angle,
    category: topic.category,
    client_name: topic.client_name
  }
}];

const client = $('Read Client Profile1').first().json;
const allUrls = (client.sitemap_or_key_pages || '').split('\n').map(u => u.trim()).filter(Boolean);

return [{ json: { link_candidates: allUrls.slice(0, 20) } }];

const client = $('Read Client Profile1').first().json;
const urls = (client['External Links'] || '').split(/[\n,]/).map(u => u.trim()).filter(Boolean);
return [{ json: { external_link_candidates: urls.slice(0, 10) } }];

const text = items[0].json.candidates[0].content.parts[0].text;

const metaTitleMatch = text.match(/META[_ ]?TITLE:\s*(.+)/i);
const metaDescMatch = text.match(/META[_ ]?DESCRIPTION:\s*(.+)/i);
const slugMatch = text.match(/URL[_ ]?SLUG:\s*(.+)/i);

let bodyMarkdown = text
  .replace(/META[_ ]?TITLE:.*(\r?\n)?/i, '')
  .replace(/META[_ ]?DESCRIPTION:.*(\r?\n)?/i, '')
  .replace(/URL[_ ]?SLUG:.*(\r?\n)?/i, '')
  .trim();

bodyMarkdown = bodyMarkdown.replace(/^\s*#\s+.*(\r?\n)+/, '');

return [{
  json: {
    meta_title: metaTitleMatch ? metaTitleMatch[1].trim() : '',
    meta_description: metaDescMatch ? metaDescMatch[1].trim() : '',
    url_slug: slugMatch ? slugMatch[1].trim() : '',
    markdown_text: bodyMarkdown
  }
}];

const markdown = items[0].json.markdown_text || '';
const client = $('Read Client Profile1').first().json;
const brandPrimaryColor = client.brand_primary_color || client['Branding colors'] || '#3898FF';
const brandSecondaryColor = client.brand_secondary_color || '';

const paragraphs = markdown.split(/\n\n+/);
const sections = [];
let currentWordCount = 0;
let currentParagraphs = [];

paragraphs.forEach((para, idx) => {
  currentParagraphs.push(para);
  const wordsInPara = (para.match(/\S+/g) || []).length;
  currentWordCount += wordsInPara;

  if (currentWordCount >= 500) {
    sections.push({
      section_index: sections.length,
      insert_after_paragraph_index: idx,
      section_text: currentParagraphs.join('\n\n'),
      brand_primary_color: brandPrimaryColor,
      brand_secondary_color: brandSecondaryColor
    });
    currentParagraphs = [];
    currentWordCount = 0;
  }
});

const allParagraphsJson = JSON.stringify(paragraphs);

if (sections.length === 0 && paragraphs.length > 0) {
  const midIndex = Math.floor(paragraphs.length / 2);
  sections.push({
    section_index: 0,
    insert_after_paragraph_index: midIndex,
    section_text: paragraphs.slice(0, midIndex + 1).join('\n\n'),
    brand_primary_color: brandPrimaryColor,
    brand_secondary_color: brandSecondaryColor
  });
}

return sections.map(s => ({ json: { ...s, all_paragraphs: allParagraphsJson } }));

const sectionData = $('Split Body Into Image Sections1').item.json;
const parts = items[0].json.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => p.inline_data || p.inlineData);

if (!imagePart) {
  throw new Error('No image returned for section');
}

const data = imagePart.inline_data || imagePart.inlineData;
const buffer = Buffer.from(data.data, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'section-image.png', data.mime_type || data.mimeType || 'image/png');

return [{
  json: { section_text: sectionData.section_text, insert_after_paragraph_index: sectionData.insert_after_paragraph_index },
  binary: { edited: binary }
}];

const itemData = $('Split Body Into Image Sections1').item.json;
const sectionText = itemData.section_text || '';
const plainText = sectionText.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').replace(/[#*_`]/g, '').replace(/\n/g, ' ');
const altText = plainText.trim().split(/\s+/).slice(0, 10).join(' ');

const imageUrl = $json.data ? $json.data.display_url : '';
const insertAfterIndex = itemData.insert_after_paragraph_index;

return [{
  json: {
    insert_after_paragraph_index: insertAfterIndex,
    image_markdown: `<p style="text-align:center;"><img src="${imageUrl}" alt="${altText}" style="max-width:100%;height:auto;" /></p>`
  }
}];

const aggregatedItems = $json.data || [];

if (aggregatedItems.length === 0) {
  return [{ json: { markdown_text: $('Code in JavaScript3').item.json.markdown_text } }];
}

const paragraphs = JSON.parse($('Split Body Into Image Sections1').first().json.all_paragraphs);
const sorted = [...aggregatedItems].sort((a, b) => b.insert_after_paragraph_index - a.insert_after_paragraph_index);

for (const item of sorted) {
  const targetIdx = Number(item.insert_after_paragraph_index);
  if (!isNaN(targetIdx) && targetIdx >= 0 && targetIdx < paragraphs.length) {
    paragraphs.splice(targetIdx + 1, 0, item.image_markdown);
  } else {
    paragraphs.splice(Math.floor(paragraphs.length / 2), 0, item.image_markdown);
  }
}

return [{ json: { markdown_text: paragraphs.join('\n\n') } }];

const parts = items[0].json.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => p.inline_data || p.inlineData);

if (!imagePart) {
  throw new Error('No image returned from Gemini featured image generation');
}

const data = imagePart.inline_data || imagePart.inlineData;
const buffer = Buffer.from(data.data, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'featured-image.png', data.mime_type || data.mimeType || 'image/png');

return [{ json: {}, binary: { edited: binary } }];

const json = items[0].json;
return [{
  json: {
    markdown_text: json.markdown_text,
    featured_image_url: json.featured_image_url || ''
  }
}];

const html = $json.html;
const client =$('Read Client Profile1').first().json;
const primaryColor = client.brand_primary_color || client['Branding colors'] || '#3898FF';

const styleBlock = `<style>
.blog-content h2,.blog-content h3{color:${primaryColor};}
.blog-content ul{list-style:disc;padding-left:24px;margin:16px 0;}
.blog-content ol{list-style:decimal;padding-left:24px;margin:16px 0;}
.blog-content li{margin-bottom:8px;}
.blog-content ul li::marker,.blog-content ol li::marker{color:${primaryColor};}
.blog-content img{display:block;margin:0 auto;max-width:100%;height:auto;}
.blog-content .faq-item{border-left:4px solid ${primaryColor};padding:12px 16px;margin-bottom:16px;background:rgba(0,0,0,0.02);}
.blog-content .faq-item strong{color:${primaryColor};}
.blog-content .faq-item .faq-number{color:${primaryColor};font-weight:bold;margin-right:6px;}
</style>`;

const faqSplit = html.split(/(<h2[^>]*>\s*Frequently Asked Questions[\s\S]*?<\/h2>)/i);
let bodyHtml;
if (faqSplit.length === 3) {
  const [before, heading, after] = faqSplit;
  let faqIndex = 0;
  const wrappedAfter = after.replace(/<p><strong>(.*?)<\/strong>\s*([\s\S]*?)<\/p>/g,
    (match, question, answer) => {
      faqIndex++;
      return `<div class="faq-item"><p><span class="faq-number">${faqIndex}.</span> <strong>${question}</strong></p><p>${answer}</p></div>`;
    }
  );
  bodyHtml = before + heading + wrappedAfter;
} else {
  bodyHtml = html;
}

const finalHtml = `<div class="blog-content">${styleBlock}${bodyHtml}</div>`;
const ctaLink = client['CTA Link'] || '#';
const ctaText = client.cta_text || 'Get Started';
const ctaButton = `<p style="text-align:center;margin-top:32px;"><a href="${ctaLink}" style="display:inline-block;background-color:${primaryColor};color:#ffffff;padding:14px 32px;border-radius:6px;text-decoration:none;font-weight:bold;">${ctaText}</a></p>`;

return [{ json: { final_html: finalHtml + ctaButton } }];

// Send the finished article to the dashboard for review.
// The dashboard pushes it to WordPress after someone approves it.
const codeOutput = $('Code in JavaScript3').first().json;
const topic = $('Loop Over Items1').first().json;
const publish = $('Prepare Publish Data1').first().json;

const body = {
  meta_title: codeOutput.meta_title,
  meta_description: codeOutput.meta_description,
  url_slug: codeOutput.url_slug,
  content_html: $('Style Blog Content2').first().json.final_html
};
if (publish.featured_image_url) body.featured_image_url = publish.featured_image_url;

return [{ json: { topic_id: topic.topic_id, body } }];
